/*
 * The step's own copy of its form (DBU-10), as one record per question for Checkin/Question.
 * Ids carry the step, so two check-ins with the same form never share an answer. Reading the
 * check-in again keeps what is already typed or picked.
 */
if (Inputs.stepId === undefined || Inputs.questions === undefined) return;
const step = String(Inputs.stepId || '');
const qs = (Array.isArray(Inputs.questions) ? Inputs.questions : []).filter((q) => q && q.id);
const OFF = { bg: 'var(--surface)', fg: 'var(--foreground)', border: 'var(--border-control)' };
const ON = { bg: 'var(--primary)', fg: 'var(--primary-foreground)', border: 'var(--primary)' };
const before = {};
(Noodl.Arrays['checkin-questions'] || []).forEach((m) => { before[m.getId()] = m.get('value'); });
const rows = qs.map((q) => {
  const id = 'cq-' + step + '-' + q.id;
  const type = String(q.type || 'text');
  const kept = before[id];
  const value = kept !== undefined ? kept : (type === 'checkbox' ? [] : '');
  const on = (v) => (Array.isArray(value) ? value.includes(v) : value === v);
  let choices = [];
  if (type === 'scale') {
    const lo = Number.isFinite(q.min) ? q.min : 1;
    const hi = Number.isFinite(q.max) ? q.max : 5;
    for (let n = lo; n <= hi; n += 1) choices.push({ id: id + '-' + n, label: String(n), value: n });
  } else if (type === 'radio' || type === 'checkbox') {
    choices = (Array.isArray(q.options) ? q.options : []).map((o) => {
      const v = o && typeof o === 'object' ? o.value : o;
      return { id: id + '-' + v, label: String(o && typeof o === 'object' ? (o.label || v) : v), value: v };
    });
  }
  choices = choices.map((c) => Object.assign(c, on(c.value) ? ON : OFF));
  return {
    id, qid: q.id, type, condition: q.condition || null, value,
    labelKey: q.required ? 'checkin.qRequired' : 'checkin.qOptional',
    label: String(q.label || q.id), hint: String(q.hint || ''), hasHint: !!q.hint,
    shown: true, choices, hasChoices: choices.length > 0,
    hasEnds: type === 'scale' && !!(q.minLabel || q.maxLabel),
    minLabel: String(q.minLabel || ''), maxLabel: String(q.maxLabel || ''),
    isLine: type === 'text' || type === 'number', inputMode: type === 'number' ? 'decimal' : 'text',
    isLong: type === 'textarea', suffix: String(q.suffix || ''), hasSuffix: !!q.suffix,
    text: typeof value === 'string' ? value : ''
  };
});
Noodl.Arrays['checkin-questions'] = rows;
Outputs.built();

/*
 * WHICH QUESTIONS SHOW (DBU-10): the Hub's SurveyForm rules, the same as answerCheckin's, so the
 * page never asks what the server would drop. In question order, a question shows when its condition
 * holds on the answers above it that show: {field, value | [values]}, {field, not}, {field, operator, value}.
 * The answers gathered are only the shown, non-empty ones. A number is sent as typed (the server
 * reads a comma as a point); a scale point and a pick are sent as their values.
 */
const list = Noodl.Arrays['checkin-questions'] || [];
const empty = (v) => v === undefined || v === null || (typeof v === 'string' && !v.trim()) || (Array.isArray(v) && !v.length);
const holds = (c, sofar) => {
  if (!c || !c.field) return true;
  const v = sofar[c.field];
  if (Array.isArray(c.value)) return c.value.includes(v);
  if (c.operator) {
    const n = Number(v);
    if (v === undefined || !Number.isFinite(n)) return false;
    if (c.operator === '>') return n > c.value;
    if (c.operator === '<') return n < c.value;
    if (c.operator === '>=') return n >= c.value;
    if (c.operator === '<=') return n <= c.value;
    return false;
  }
  if (c.not !== undefined) return v !== c.not;
  return v === c.value;
};
const sofar = {};
const answers = {};
list.forEach((m) => {
  const show = holds(m.get('condition'), sofar);
  if (m.get('shown') !== show) m.set('shown', show);
  const v = m.get('value');
  if (!show || empty(v)) return;
  const qid = m.get('qid');
  if (m.get('type') === 'number') {
    const n = Number(String(v).trim().replace(',', '.'));
    sofar[qid] = Number.isFinite(n) ? n : v;
    answers[qid] = String(v).trim();
  } else {
    sofar[qid] = typeof v === 'string' ? v.trim() : v;
    answers[qid] = sofar[qid];
  }
});
Outputs.answers = answers;
